from app.postgres_schema import (
    POSTGRES_SCHEMA_STATEMENTS,
    apply_postgres_schema,
)


def test_schema_defines_all_four_ledger_tables():
    ddl = "\n".join(POSTGRES_SCHEMA_STATEMENTS).lower()

    for table in (
        "predictions",
        "prediction_observations",
        "trades",
        "multi_exchange_reference",
    ):
        assert f"create table if not exists {table}" in ddl


def test_schema_preserves_legacy_columns_and_types():
    ddl = "\n".join(POSTGRES_SCHEMA_STATEMENTS).lower()

    required_fragments = (
        "generated by default as identity primary key",
        "settled smallint not null default 0",
        "is_official_lock smallint not null default 0",
        "brti_cohort text not null default 'unknown'",
        "settled_at text",
        "primary_spot_age_seconds double precision",
        "official_brti_age_seconds double precision",
        "reference_vs_strike_bps double precision",
    )
    for fragment in required_fragments:
        assert fragment in ddl


def test_schema_preserves_all_lookup_indexes_and_unique_official_lock():
    ddl = "\n".join(POSTGRES_SCHEMA_STATEMENTS).lower()

    for index_name in (
        "idx_pred_ticker",
        "idx_pred_settled",
        "idx_observation_contract_epoch",
        "idx_trades_ticker",
        "idx_multi_ref_epoch",
        "idx_multi_ref_contract",
        "idx_one_official_prediction_per_contract",
    ):
        assert index_name in ddl

    assert "unique index if not exists idx_one_official_prediction_per_contract" in ddl
    assert "where is_official_lock = 1" in ddl


def test_schema_application_executes_statements_without_committing():
    calls = []

    class Cursor:
        def __enter__(self):
            return self

        def __exit__(self, *_args):
            return False

        def execute(self, statement):
            calls.append(statement)

    class Connection:
        def cursor(self):
            return Cursor()

        def commit(self):
            raise AssertionError("schema helper must not commit caller transaction")

    apply_postgres_schema(Connection())
    assert calls == list(POSTGRES_SCHEMA_STATEMENTS)
